              className="md:hidden w-11 h-11 flex flex-col justify-center items-center gap-[5px] bg-slate-50 hover:bg-white rounded-full shadow-[0_0_15px_rgba(255,255,255,0.1)] hover:scale-105 active:scale-95 transition-all shrink-0 z-[70]"
